def update_exams(file_path):
    data = []
    if os.path.exists(file_path):
        with open(file_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    
    found = False
    for i, ex in enumerate(data):
        if ex.get('id') == 'exam-5' or ex.get('id') == 'exam-05':
            data[i] = exam5_data
            found = True
            break
    if not found:
        data.append(exam5_data)
    
    with open(file_path, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"Successfully updated {file_path} with new exam-5 data!")

update_exams('data/exams.json')
update_exams('data/default_exams.json')
